 if(s.groundDormant)return;
 const blade=(at,az,L,pitch,W=a.leafWidth/a.leafLength*L)=>flowerFrame(b,at,pitch,az).add('mixed-leaf-'+type,'leaf-mixed-'+type,kit.shade(rand,green,.035),0,0,0,W,L,L);
