   const t=i/rows,u=j/cols*2-1,sn=Math.max(0,Math.sin(Math.PI*t)),pt=betonyLeafPoint('lambEar',t,u),thick=.011*Math.sqrt(Math.max(0,1-u*u))*Math.sqrt(sn);
