    const y=.10+layer*(type==='kifujin'?.018:.038)+cup*t*t+.11*u*u*sn+ruffle+(type==='kifujin'?.035*Math.sin(k*2.7+layer)*t:0),x=u*width*(1+(herbal?.01:.05)*Math.sin(t*27+k));
