  for(let j=1;j<=6;j++)b.branch(path((j-1)/6),path(j/6),(woody?(order?.006:.016):.003)*(1-j*.08),woody&&order===0?a.barkColor:a.stemColor,woody?'wood-peony':'stem-peony');
