  const az=k*2.399963;branch([Math.sin(az)*w*.025,0,Math.cos(az)*w*.025],az,h*(broom?.67+rand()*.20:.70+rand()*.17),w*(broom?.14+rand()*.10:.35+rand()*.07),0);
