  const az=i*2.399963+rand()*.5,offset=mixed?(group===0?-1:1)*w*.18:0,r=w*(mixed?.16:.28)*Math.sqrt((i+.5)/N),top=h*(.48+rand()*.37),base=[offset+Math.sin(az)*r*.40,0,Math.cos(az)*r*.40],count=7;let last=base;
