  const f=flowerFrame(b,at,.10+.10*noise(key,121),az),bud=!cup&&noise(key,131)>Math.max(.1,s.flowerDensity??1)*.97;
  // Involucre diameter 15 mm, distinct from the approximately 35-40 mm whole head.
