   const aa=j*TAU/9+ring*.32,rr=.0030+ring*.0005,L=ring?.0057:.0051,W=ring?.0054:.0048,bf=flowerFrame(f,point(aa,rr,-.0046),cup||bud?.40:1.12,aa);
