  if(i>=(winter?4:7)&&noise(i,101)>density)continue;
  const az=i*2.399963,rr=w*.018*Math.sqrt((i+.5)/basalCount),at=[Math.sin(az)*rr,.005*scale,Math.cos(az)*rr],short=winter?.34:1;
