  const bud=budSeason||(!spent&&noise(i,151)>Math.max(.1,s.flowerDensity??1)*.95),open=!spent&&!bud,f=flowerFrame(b,heads[i],.10+.12*noise(i,157),i*2.399963),D=R*.31;
