 if(type.endsWith('Lip'))return [u*(.020+(pink?.11:blue?.070:.13)*sn)*(1+.065*Math.cos(u*Math.PI*3)),-.015-.30*t+.04*Math.sin(t*TAU),.61+.36*t-.09*t*t];
