    const aa=az+j*Math.PI/2+q*TAU/4,ped=F*.21,pos=[at[0]+Math.sin(aa)*ped,at[1]+ped*.20,at[2]+Math.cos(aa)*ped],pitch=.02+.24*noise(i,j*19+q),f=flowerFrame(b,pos,pitch,aa),fl=F*(.80+.20*noise(i,j*17+q));
