  const t=.16+.66*(i+.5)/count,at=axis(t),az=i*2.399963,reach=Math.max(.005,w*.45-oldL)*(.87-.34*t),tip=[at[0]+Math.sin(az)*reach,Math.min(h*.94*foliageScale,at[1]+h*(.13+.11*shape(i,2))*foliageScale),at[2]+Math.cos(az)*reach];
