  const an=i*2.399963,shape=k=>.5+.5*Math.sin((i+1)*18.17+k*9.23),height=h*(.65+.30*shape(1)),len=Math.min(a.inflorescenceLength,height*.25),lean=w*(.08+.16*shape(2));
