   const branchYaw=yaw+radial*TAU/3,end=[at[0]+Math.sin(branchYaw)*width,at[1]+len*.055,at[2]+Math.cos(branchYaw)*width];tinyAxis(b,at,end,.00023,stem,'branch-melinis');
