    const q=(k+.5)/5,turn=branchYaw+(k%2?1:-1)*.75,spread=len*.05*(.55+.45*q),from=[at[0]+(end[0]-at[0])*q,at[1]+(end[1]-at[1])*q,at[2]+(end[2]-at[2])*q];
