  const v=type==='clusterBellRim'?.87+t*.13:t,lobe=.5+.5*Math.cos(u*5),rim=Math.pow(v,8),r=(.06+.78*v+.16*Math.sin(v*Math.PI))*(1-.08*(1-lobe)*rim)*(type==='clusterBellRim'?1.003:1);
