  for(let q=0;q<5;q++){const t=.18+q*.15,side=q%2?1:-1,p=tapienRunnerPoint('tapienDissectedLeaf',t,side*.7).map(v=>v*len);f.branch(p,[p[0],p[1],p[2]-.00055],.00004,'#c3caaa','leaf-hair-'+tag);}
