  const reach=size*.45,tip=[root[0]+Math.sin(angle)*reach,root[1]+rise,root[2]+Math.cos(angle)*reach],bend=[root[0]+Math.sin(angle)*reach*.45,root[1]+rise*.72,root[2]+Math.cos(angle)*reach*.45];
