  if(teasel){f.branch([0,0,.002],[0,len,.002],len*.003,'#adb897','leafMidrib');for(let j=0;j<9;j++){const t=.12+j*.09;f.branch([0,len*t,.003],[0,len*t+.003,.008],.00035,'#bdc5a6','leafSpine');}}
