    const aa=yaw+(side?1:-1)*.75,reach=Math.min(w*.16,L*(brachy?2.2:2.6)),end=[at[0]+Math.sin(aa)*reach,Math.min(h*.86,at[1]+h*(brachy?.07:.10)),at[2]+Math.cos(aa)*reach];line(at,end,.00045);
