      for(let j=1;j<=4;j++)for(let side=0;side<2;side++)sites.push({at:mix(node,last,j/4),yaw:forkAngle+side*Math.PI+j*Math.PI/2,pitch:.6+rand()*1.15,roll:(rand()-.5)*.65,size:.77+rand()*.23,tone:rand(),chance:rand(),young:j===4});
