   const u=.20+k*.19,at=lerp(base,end,u),sideAz=az+side*(.70+rand()*.15),reach=extent*(.28-.10*u),out=[at[0]+Math.sin(sideAz)*reach,at[1]+h*(cord?.025:yew?.045:.065)*(1-t),at[2]+Math.cos(sideAz)*reach];
