   const yaw=k*2.399,R=L*(.035+.16*Math.sqrt((k+.5)/48)),base=[Math.sin(yaw)*R,L*.055,Math.cos(yaw)*R],tip=[Math.sin(yaw)*R*1.12,L*(.27+.18*(1-k/48)),Math.cos(yaw)*R*1.12];
