    for(let k=0;k<11;k++){const q=.50+k*.045,at=base.map((v,l)=>v+(tip[l]-v)*q);leaves.push({at,shape:'narrow',size:Math.min(.075,w*.16),yaw:aa+k*2.399,pitch:.70});}
