   const an=j*2.399+k*Math.PI,len=ll*(.44+.56*Math.sin(Math.PI*(t*.88+.03))),reach=len*.40,leafAt=[at[0]+Math.sin(an)*reach,at[1]+len*.14,Math.cos(an)*reach];
