    for(let k=0;k<19;k++)for(const side of [-1,1]){const t=.12+k*.045,ll=len*.22*Math.pow(Math.sin(Math.PI*t),.72);f.add('narrow','leaf',kit.shade(rand,green,.05),0,len*t,0,ll*.61,ll,ll,.08,0,-side*(1.1+.20*t));}
