    for(let k=0;k<3;k++){const aa=k*TAU/3;f.add('waterPetal','petal','#f4f2e5',0,0,0,r,r,r,1.42,aa,0);f.add('narrow','sepal','#6b824c',0,-r*.08,0,r*.3,r*.45,r*.45,1.6,aa+.5,0);}
