    for(let k=0;k<34;k++){const aa=k*2.399,rrr=r*.24*Math.sqrt((k+.5)/34);f.add(kit.bud,'stigma','#a0af60',Math.sin(aa)*rrr,r*(.17+.12*Math.sqrt(1-(rrr/r/.25)**2)),Math.cos(aa)*rrr,r*.026,r*.029,r*.026);}
